package dashboard

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/integrio-intropy/intropy-cli/internal/deploy"
	"golang.org/x/term"
)

// CatalogTUIOptions configures the terminal catalog browser.
type CatalogTUIOptions struct {
	// Root is the workspace directory scanned for integrations.
	Root string
	// Version is used in the deploy status user agent.
	Version string
	// Stdin must be a terminal so the browser can read key presses in raw mode.
	Stdin *os.File
	// Stdout must be a terminal; it receives the screen contents.
	Stdout io.Writer
	// Stderr receives non-screen diagnostics.
	Stderr io.Writer
}

type catalogTUI struct {
	ctx context.Context
	api *apiServer

	in  *os.File
	out io.Writer

	entries       []integrationSummary
	selected      int
	deployStates  map[string]deployState
	deployLoading map[string]bool
	deployErrs    map[string]string
	refreshing    bool
	message       string
	width         int
	height        int
}

type catalogTUIEvent struct {
	key        string
	path       string
	deploy     *deployState
	deployErr  error
	refreshed  bool
	refreshErr error
}

// ServeCatalogTUI opens an interactive terminal catalog. It reads the same
// catalog and deployment facts as the browser dashboard, but renders them in a
// keyboard-first view for terminal sessions.
func ServeCatalogTUI(ctx context.Context, opts CatalogTUIOptions) error {
	if opts.Stdin == nil {
		opts.Stdin = os.Stdin
	}
	if opts.Stdout == nil {
		opts.Stdout = os.Stdout
	}
	if opts.Stderr == nil {
		opts.Stderr = os.Stderr
	}
	if !term.IsTerminal(int(opts.Stdin.Fd())) {
		return fmt.Errorf("dashboard tui: stdin must be a terminal")
	}
	if f, ok := opts.Stdout.(*os.File); ok && !term.IsTerminal(int(f.Fd())) {
		return fmt.Errorf("dashboard tui: stdout must be a terminal")
	}

	state, err := term.MakeRaw(int(opts.Stdin.Fd()))
	if err != nil {
		return fmt.Errorf("dashboard tui: raw mode: %w", err)
	}
	defer func() { _ = term.Restore(int(opts.Stdin.Fd()), state) }()

	root := opts.Root
	if root == "" {
		root = "."
	}
	tui := &catalogTUI{
		ctx:           ctx,
		api:           &apiServer{root: root, version: opts.Version, topo: hostGraphProvider(root), dep: statusCommandProvider(opts.Version)},
		in:            opts.Stdin,
		out:           opts.Stdout,
		deployStates:  map[string]deployState{},
		deployLoading: map[string]bool{},
		deployErrs:    map[string]string{},
		width:         100,
		height:        32,
	}
	tui.reloadEntries()
	if len(tui.entries) > 0 {
		tui.ensureDeploy(false)
	}

	fmt.Fprint(tui.out, "\x1b[?1049h\x1b[?25l")
	defer fmt.Fprint(tui.out, "\x1b[?25h\x1b[?1049l")

	events := make(chan catalogTUIEvent, 16)
	go readCatalogTUIKeys(opts.Stdin, events)
	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()

	tui.render()
	for {
		select {
		case <-ctx.Done():
			return nil
		case <-ticker.C:
			tui.measure()
			tui.render()
		case ev := <-events:
			if tui.handle(ev, events) {
				return nil
			}
			tui.render()
		}
	}
}

func readCatalogTUIKeys(in *os.File, events chan<- catalogTUIEvent) {
	r := bufio.NewReader(in)
	for {
		b, err := r.ReadByte()
		if err != nil {
			events <- catalogTUIEvent{key: "quit"}
			return
		}
		switch b {
		case 3:
			events <- catalogTUIEvent{key: "quit"}
		case 'q':
			events <- catalogTUIEvent{key: "quit"}
		case 'j':
			events <- catalogTUIEvent{key: "down"}
		case 'k':
			events <- catalogTUIEvent{key: "up"}
		case 'r':
			events <- catalogTUIEvent{key: "refresh"}
		case 0x1b:
			b2, err := r.ReadByte()
			if err != nil {
				events <- catalogTUIEvent{key: "quit"}
				return
			}
			if b2 != '[' {
				continue
			}
			b3, err := r.ReadByte()
			if err != nil {
				events <- catalogTUIEvent{key: "quit"}
				return
			}
			switch b3 {
			case 'A':
				events <- catalogTUIEvent{key: "up"}
			case 'B':
				events <- catalogTUIEvent{key: "down"}
			}
		}
	}
}

func (t *catalogTUI) handle(ev catalogTUIEvent, events chan<- catalogTUIEvent) bool {
	switch ev.key {
	case "quit":
		return true
	case "up":
		if t.selected > 0 {
			t.selected--
			t.message = ""
			t.ensureDeploy(false)
		}
	case "down":
		if t.selected+1 < len(t.entries) {
			t.selected++
			t.message = ""
			t.ensureDeploy(false)
		}
	case "refresh":
		t.refresh(events)
	}
	if ev.path != "" {
		t.deployLoading[ev.path] = false
		if ev.deploy != nil {
			t.deployStates[ev.path] = *ev.deploy
			delete(t.deployErrs, ev.path)
		}
		if ev.deployErr != nil {
			t.deployErrs[ev.path] = ev.deployErr.Error()
		}
	}
	if ev.refreshed {
		t.refreshing = false
		t.message = "refreshed catalog"
	}
	if ev.refreshErr != nil {
		t.refreshing = false
		t.message = ev.refreshErr.Error()
	}
	return false
}

func (t *catalogTUI) refresh(events chan<- catalogTUIEvent) {
	if t.refreshing {
		return
	}
	t.refreshing = true
	t.message = "refreshing catalog"
	selectedPath := t.selectedPath()
	go func() {
		_, _ = t.api.cachedTopologies(t.ctx, true)
		t.reloadEntries()
		if selectedPath != "" {
			for i, e := range t.entries {
				if e.Path == selectedPath {
					t.selected = i
					break
				}
			}
		}
		events <- catalogTUIEvent{refreshed: true}
		t.ensureDeploy(true)
	}()
}

func (t *catalogTUI) reloadEntries() {
	entries, systems := t.api.scan()
	summaries := make([]integrationSummary, 0, len(entries))
	for _, e := range entries {
		summaries = append(summaries, t.api.summarize(e, systems))
	}
	sort.SliceStable(summaries, func(i, j int) bool { return summaries[i].Path < summaries[j].Path })
	t.entries = summaries
	if t.selected >= len(t.entries) {
		t.selected = len(t.entries) - 1
	}
	if t.selected < 0 {
		t.selected = 0
	}
}

func (t *catalogTUI) ensureDeploy(force bool) {
	path := t.selectedPath()
	if path == "" || t.deployLoading[path] {
		return
	}
	if _, ok := t.deployStates[path]; ok && !force {
		return
	}
	t.deployLoading[path] = true
	go func(sum integrationSummary) {
		state := t.api.cachedDeployState(t.ctx, sum, force)
		// The main loop owns maps; this goroutine only sends the result.
		// A best-effort channel send keeps shutdown from waiting on the UI.
		select {
		case <-t.ctx.Done():
		case catalogTUIEvents <- catalogTUIEvent{}:
		default:
		}
	}(t.entries[t.selected])
}

var catalogTUIEvents chan<- catalogTUIEvent

func (t *catalogTUI) selectedPath() string {
	if len(t.entries) == 0 || t.selected < 0 || t.selected >= len(t.entries) {
		return ""
	}
	return t.entries[t.selected].Path
}

func (t *catalogTUI) measure() {
	if w, h, err := term.GetSize(int(t.in.Fd())); err == nil {
		t.width, t.height = w, h
	}
}

func (t *catalogTUI) render() {
	t.measure()
	fmt.Fprint(t.out, "\x1b[H\x1b[2J")
	fmt.Fprint(t.out, renderCatalogTUIScreen(t.snapshot()))
}

type catalogTUIScreen struct {
	Width         int
	Height        int
	Entries       []integrationSummary
	Selected      int
	Catalog       CatalogEntry
	Deploy        deployState
	DeployLoading bool
	DeployError   string
	Message       string
	Refreshing    bool
}

func (t *catalogTUI) snapshot() catalogTUIScreen {
	var cat CatalogEntry
	var dep deployState
	path := t.selectedPath()
	if path != "" {
		sum := t.entries[t.selected]
		entries, systems := t.api.scan()
		_ = entries
		loaded, topologies, errs := t.api.topologiesLoaded()
		if !loaded {
			t.api.warmTopologies()
		}
		cat = buildCatalogEntry(sum, systems, loaded, topologies, errs)
		dep = t.deployStates[path]
	}
	return catalogTUIScreen{
		Width:         t.width,
		Height:        t.height,
		Entries:       t.entries,
		Selected:      t.selected,
		Catalog:       cat,
		Deploy:        dep,
		DeployLoading: t.deployLoading[path],
		DeployError:   t.deployErrs[path],
		Message:       t.message,
		Refreshing:    t.refreshing,
	}
}

func renderCatalogTUIScreen(s catalogTUIScreen) string {
	width := s.Width
	if width < 60 {
		width = 60
	}
	height := s.Height
	if height < 12 {
		height = 12
	}
	leftW := width / 3
	if leftW < 24 {
		leftW = 24
	}
	if leftW > 42 {
		leftW = 42
	}
	rightW := width - leftW - 3

	left := renderCatalogTUIList(s, leftW, height-3)
	right := renderCatalogTUIDetail(s, rightW)
	lines := make([]string, 0, height)
	for i := 0; i < height-2; i++ {
		l, r := "", ""
		if i < len(left) {
			l = left[i]
		}
		if i < len(right) {
			r = right[i]
		}
		lines = append(lines, pad(truncate(l, leftW), leftW)+" │ "+truncate(r, rightW))
	}
	status := "q quit · ↑/k up · ↓/j down · r refresh"
	if s.Message != "" {
		status += " · " + s.Message
	}
	lines = append(lines, strings.Repeat("─", width))
	lines = append(lines, truncate(status, width))
	return strings.Join(lines, "\r\n")
}

func renderCatalogTUIList(s catalogTUIScreen, width, height int) []string {
	lines := []string{"Integrations", strings.Repeat("─", width)}
	if len(s.Entries) == 0 {
		return append(lines, "no integrations")
	}
	visible := height - len(lines)
	start := 0
	if s.Selected >= visible {
		start = s.Selected - visible + 1
	}
	for i := start; i < len(s.Entries) && len(lines) < height; i++ {
		entry := s.Entries[i]
		mark := "  "
		if i == s.Selected {
			mark = "> "
		}
		label := entry.Name
		if entry.System != "" {
			label += "  " + entry.System
		}
		lines = append(lines, mark+label)
		if entry.Domain != "" && len(lines) < height {
			lines = append(lines, "  "+entry.Domain+"/"+entry.System)
		}
	}
	return lines
}

func renderCatalogTUIDetail(s catalogTUIScreen, width int) []string {
	if len(s.Entries) == 0 {
		return []string{"Catalog", "", "No integrations to browse."}
	}
	cat := s.Catalog
	lines := []string{cat.Component}
	meta := []string{}
	if cat.Kind != "" {
		meta = append(meta, cat.Kind)
	}
	if cat.System != "" {
		meta = append(meta, cat.System)
	}
	meta = append(meta, "graph: "+cat.GraphStatus)
	lines = append(lines, strings.Join(meta, " · "))
	if cat.Repository != "" {
		lines = append(lines, cat.Repository)
	}
	lines = append(lines, "")
	lines = append(lines, "Contracts")
	lines = append(lines, "  publishes: "+contractLine(cat.Publishes))
	lines = append(lines, "  subscribes: "+contractLine(cat.Subscribes))
	if cat.TopologyPending {
		lines = append(lines, "  computing system graph")
	}

	checks := collectCatalogTUIChecks(cat, s.Deploy)
	if len(checks) > 0 {
		lines = append(lines, "", "Checks")
		for _, c := range checks {
			lines = append(lines, wrapBullet(c.Severity+": "+c.Message, width, "  ")...)
		}
	}

	lines = append(lines, "", "Environments")
	if s.DeployError != "" {
		lines = append(lines, wrapBullet(s.DeployError, width, "  ")...)
	} else if s.DeployLoading && s.Deploy.Status == nil && s.Deploy.Error == "" {
		lines = append(lines, "  reading deployment state")
	} else if s.Deploy.Error != "" {
		lines = append(lines, wrapBullet(s.Deploy.Error, width, "  ")...)
	} else if s.Deploy.Status != nil {
		lines = append(lines, renderCatalogTUIEnvironments(s.Deploy.Status, width)...)
	} else {
		lines = append(lines, "  no deployment state")
	}
	return lines
}

func collectCatalogTUIChecks(entry CatalogEntry, state deployState) []Check {
	warns := []Check{}
	infos := []Check{}
	for _, c := range entry.Checks {
		if c.Severity == severityWarn {
			warns = append(warns, c)
		} else {
			infos = append(infos, c)
		}
	}
	if state.Status != nil {
		for _, env := range state.Status.Environments {
			if !env.Onboarded {
				continue
			}
			for _, pin := range env.Pins {
				if pin.Digest != "" {
					continue
				}
				msg := fmt.Sprintf("%s pins nothing for %s, so it has never been deployed there", env.Environment, pin.Image)
				if pin.Tag != "" {
					msg = fmt.Sprintf("%s pins %s to the tag %q rather than a digest — it can drift without a deployment", env.Environment, pin.Image, pin.Tag)
				}
				warns = append(warns, Check{Severity: severityWarn, Message: msg})
			}
		}
	}
	return append(warns, infos...)
}

func renderCatalogTUIEnvironments(status *deploy.StatusResult, width int) []string {
	lines := []string{}
	if status.Consistent && status.Summary != "" {
		lines = append(lines, wrapBullet(status.Summary, width, "  ")...)
	}
	if len(status.Environments) == 0 {
		return append(lines, "  this component declares no environments")
	}
	for _, env := range status.Environments {
		if !env.Onboarded {
			reason := env.Reason
			if reason == "" {
				reason = "no readable overlay here"
			}
			lines = append(lines, fmt.Sprintf("  %-12s %s", env.Environment, reason))
			continue
		}
		version := env.Release
		if version == "" {
			version = short(env.SourceCommit, 7)
		}
		if version == "" {
			version = "—"
		}
		statusText := env.SyncStatus
		if env.HealthStatus != "" {
			if statusText != "" {
				statusText += " · "
			}
			statusText += env.HealthStatus
		}
		if statusText == "" {
			statusText = "sync unknown"
		}
		lines = append(lines, fmt.Sprintf("  %-12s %-12s %-18s %s", env.Environment, version, pinsLine(env), statusText))
	}
	for _, note := range status.Notes {
		lines = append(lines, wrapBullet(note, width, "  note: ")...)
	}
	return lines
}

func contractLine(edges []ContractEdge) string {
	if len(edges) == 0 {
		return "—"
	}
	parts := make([]string, 0, len(edges))
	for _, edge := range edges {
		label := edge.Topic
		if edge.Contract != "" {
			label += " (" + edge.Contract + ")"
		}
		parts = append(parts, label)
	}
	return strings.Join(parts, ", ")
}

func pinsLine(env deploy.EnvironmentStatus) string {
	if len(env.Pins) == 0 {
		return "—"
	}
	parts := make([]string, 0, len(env.Pins))
	for _, pin := range env.Pins {
		label := shortImage(pin.Image)
		if pin.Digest != "" {
			label += "@" + shortDigest(pin.Digest)
		} else if pin.Tag != "" {
			label += ":" + pin.Tag
		} else {
			label += ":—"
		}
		parts = append(parts, label)
	}
	return strings.Join(parts, ",")
}

func shortImage(image string) string {
	if i := strings.LastIndex(image, "/"); i >= 0 && i+1 < len(image) {
		return image[i+1:]
	}
	return image
}

func shortDigest(digest string) string {
	if i := strings.IndexByte(digest, ':'); i >= 0 && i+1 < len(digest) {
		return short(digest[i+1:], 12)
	}
	return short(digest, 12)
}

func short(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n]
}

func wrapBullet(text string, width int, prefix string) []string {
	if width <= len(prefix)+8 {
		return []string{prefix + text}
	}
	limit := width - len(prefix)
	words := strings.Fields(text)
	if len(words) == 0 {
		return []string{prefix}
	}
	lines := []string{}
	line := ""
	for _, word := range words {
		if line == "" {
			line = word
			continue
		}
		if visibleLen(line)+1+visibleLen(word) > limit {
			lines = append(lines, prefix+line)
			line = word
			continue
		}
		line += " " + word
	}
	if line != "" {
		lines = append(lines, prefix+line)
	}
	return lines
}

func pad(s string, width int) string {
	if visibleLen(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-visibleLen(s))
}

func truncate(s string, width int) string {
	if width <= 0 || visibleLen(s) <= width {
		return s
	}
	if width == 1 {
		return "…"
	}
	out := ""
	for _, r := range s {
		if visibleLen(out)+1 >= width {
			return out + "…"
		}
		out += string(r)
	}
	return out
}

func visibleLen(s string) int {
	return utf8.RuneCountInString(s)
}

