package dashboard

import (
	"strings"
	"testing"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/deploy"
	"github.com/integrio-intropy/intropy-cli/internal/template"
)

func TestRenderCatalogTUIScreenShowsCatalogAndDeploymentFacts(t *testing.T) {
	readAt := time.Date(2026, 8, 6, 12, 0, 0, 0, time.UTC)
	screen := renderCatalogTUIScreen(catalogTUIScreen{
		Width:  120,
		Height: 30,
		Entries: []integrationSummary{{
			ScaffoldEntry: template.ScaffoldEntry{Path: "sales/orders/order-loader"},
			Name:          "order-loader",
			System:        "orders",
			Domain:        "sales",
		}},
		Catalog: CatalogEntry{
			Component:    "order-loader",
			Kind:         "loader",
			System:       "orders",
			Repository:   "integrio-intropy/intropy-templates",
			GraphStatus:  graphMatched,
			Publishes:    []ContractEdge{{Topic: "orders-loaded", Contract: "OrderLoaded"}},
			Subscribes:   []ContractEdge{{Topic: "orders-raw", Contract: "RawOrder"}},
			Checks:       []Check{{Severity: severityInfo, Message: "system graph matched order-loader"}},
		},
		Deploy: deployState{
			ReadAt: readAt,
			Status: &deploy.StatusResult{
				Consistent: true,
				Summary:    "dev and staging run the same image digest",
				Environments: []deploy.EnvironmentStatus{{
					Environment:  "dev",
					Onboarded:    true,
					Release:      "1.2.3",
					Pins:         []deploy.ResultPin{{Image: "ghcr.io/acme/order-loader", Digest: "sha256:1234567890abcdef"}},
					SyncStatus:   "Synced",
					HealthStatus: "Healthy",
				}},
				Notes: []string{"staging waits for manual sync"},
			},
		},
	})

	for _, want := range []string{
		"order-loader",
		"loader · orders · graph: matched",
		"integrio-intropy/intropy-templates",
		"publishes: orders-loaded (OrderLoaded)",
		"subscribes: orders-raw (RawOrder)",
		"info: system graph matched order-loader",
		"dev and staging run the same image digest",
		"dev          1.2.3",
		"order-loader@1234567890ab",
		"Synced · Healthy",
		"note: staging waits for manual sync",
	} {
		if !strings.Contains(screen, want) {
			t.Errorf("rendered screen missing %q:\n%s", want, screen)
		}
	}
}

func TestCollectCatalogTUIChecksKeepsWarningsBeforeInfos(t *testing.T) {
	checks := collectCatalogTUIChecks(CatalogEntry{
		Checks: []Check{{Severity: severityInfo, Message: "topology pending"}},
	}, deployState{Status: &deploy.StatusResult{Environments: []deploy.EnvironmentStatus{{
		Environment: "dev",
		Onboarded:   true,
		Pins:        []deploy.ResultPin{{Image: "ghcr.io/acme/api", Tag: "latest"}},
	}}}})

	if len(checks) != 2 {
		t.Fatalf("checks = %d, want 2", len(checks))
	}
	if checks[0].Severity != severityWarn || !strings.Contains(checks[0].Message, "latest") {
		t.Fatalf("first check = %+v, want tag warning", checks[0])
	}
	if checks[1].Severity != severityInfo || checks[1].Message != "topology pending" {
		t.Fatalf("second check = %+v, want original info", checks[1])
	}
}

